<?php
namespace App\Livewire\Payroll;
use App\Models\PayrollRun; use App\Services\PayrollRunService; use Livewire\Component;
class Runs extends Component { public int $month;public int $year;public string $runType='regular';public string $label='';public function mount():void{$this->month=(int)now()->month;$this->year=(int)now()->year;}public function create(PayrollRunService $s):void{$this->authorize('payroll.calculate');$this->validate(['month'=>'integer|min:1|max:12','year'=>'integer|min:2000|max:2200','runType'=>'required|in:regular,off_cycle','label'=>'nullable|string|max:255']);try{$s->createRun($this->month,$this->year,auth()->id(),$this->runType,$this->label?:null);$this->label='';session()->flash('success',__('hr.payroll_created'));}catch(\RuntimeException $e){$this->addError('payroll',$e->getMessage());}}public function process(int $id,PayrollRunService $s):void{$this->authorize('payroll.calculate');try{$s->process(PayrollRun::findOrFail($id));session()->flash('success','Payroll calculated and is ready for approval.');}catch(\RuntimeException $e){$this->addError('payroll',$e->getMessage());}}public function approve(int $id,PayrollRunService $s):void{$this->authorize('payroll.approve');try{$s->approve(PayrollRun::findOrFail($id),auth()->id());session()->flash('success','Payroll approved and locked.');}catch(\RuntimeException $e){$this->addError('payroll',$e->getMessage());}}public function render(){return view('livewire.payroll.runs',['runs'=>PayrollRun::with(['payslips.employee','complianceSetting','approver'])->withCount('payslips')->orderByDesc('year')->orderByDesc('month')->orderByDesc('sequence')->get()]);}}
